55: - name: Discover datasets/zvols with refreservation != none (excluding snapshots)
56:   ansible.builtin.shell: |
57:     set -eo pipefail
58:     pool="{{ item }}"
59:     zfs get -r -H -o name,value refreservation "${pool}" | \
60:     awk '$2 != "none" && $2 != "-" {print $0}'
61:   args:
62:     executable: /bin/bash
63:   loop: "{{ proxmox_zfs_thin_pools }}"
64:   register: proxmox_zfs_refreservation_findings
65:   changed_when: false
66:   check_mode: false
67: 
68: - name: Build consolidated findings list
69:   ansible.builtin.set_fact:
70:     proxmox_zfs_thin_datasets_to_fix: "{{ findings }}"
71:   vars:
72:     findings: >-
73:       {%- set results = [] -%}
74:       {%- for res in proxmox_zfs_refreservation_findings.results -%}
75:         {%- for line in res.stdout_lines -%}
76:           {%- set parts = line.split('\t') -%}
77:           {%- set _ = results.append({'name': parts[0], 'value': parts[1]}) -%}
78:         {%- endfor -%}
79:       {%- endfor -%}
80:       {{ results }}
81: 
82: - name: Audit report (non-thin datasets)
83:   ansible.builtin.debug:
84:     msg: |
85:       ZFS thin-provisioning audit:
86:       {% if (proxmox_zfs_thin_datasets_to_fix | default([]) | length) == 0 %}
87:       - No datasets with refreservation set (thin provisioning already in effect).
88:       {% else %}
89:       - The following datasets/zvols have refreservation != none (NOT thin):
90:       {% for item in proxmox_zfs_thin_datasets_to_fix %}
91:         * {{ item.name }} (refreservation={{ item.value }})
92:       {% endfor %}
93:       {% endif %}
94:   changed_when: false

