104: - name: Create registry path
105:   ansible.windows.win_regedit:
106:     path: "{{ registry_key }}"
107:     state: present
108:   when: splunk_dotnet_auto_instrumentation_system_wide
109: 
110: - name: Set system-wide registry value
111:   ansible.windows.win_regedit:
112:     path: "{{ registry_key }}"
113:     state: present
114:     name: "{{ item.key }}"
115:     data: |-
116:       {%- set value = item.value -%}
117:       {%- if (item.value | type_debug) == "bool" -%}
118:         {%- set value = item.value | string | lower -%}
119:       {%- endif -%}
120:       {%- if item.key == "OTEL_RESOURCE_ATTRIBUTES" -%}
121:         {%- set method = "splunk.zc.method=splunk-otel-dotnet-" + splunk_otel_dotnet_version.output[0].lstrip("v") -%}
122:         {%- set value = (item.value + "," + method) | trim(",") -%}
123:       {%- endif -%}
124:       {{ value | string }}
125:     type: string
126:   loop: >
127:     {{ dotnet_options | default({}) | combine(splunk_dotnet_auto_instrumentation_additional_options) | dict2items }}
128:   when: splunk_dotnet_auto_instrumentation_system_wide
129:   notify: "reset iis"
130:   tags: molecule-idempotence-notest
